    reg full;
    reg signed [12:0] d1, d2, d3;
    reg signed [7:0] x_prev1, x_prev2, x_prev3;

    wire r3 = !v3 || out_ready;
    wire r2 = !v2 || r3;

    assign in_ready = !full || out_ready;
    assign out_valid = v3;
    assign out_data = d3;

