    wire signed [10:0] x_prev2_11 =
        {{3{x_prev2[7]}}, x_prev2};
    wire signed [8:0] x_prev3_9 =
        {{1{x_prev3[7]}}, x_prev3};

    wire signed [9:0] term0 =
